using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "MysteriousAdventureRunModifier", menuName = "Data/RunModifiers/MysteriousAdventureRunModifier", order = 0)]
public class MysteriousAdventureRunModifier : RunModifier
{
	[Header("Specifics")]
	[SerializeField]
	private EventLocation[] eventLocations;

	[SerializeField]
	private ClearingReward chestClearingReward;

	public ClearingReward ChestClearingReward => chestClearingReward;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.MysteriousAdventureRunModifier = this;
	}

	public Location GetCurrentEventLocation()
	{
		return eventLocations[ReferenceSingleton<AssetsReference>.Instance.MapHandler.CurrentAreaIndex];
	}
}
